const token = $env.MEALIE_API_TOKEN;
if (!token) throw new Error('MEALIE_API_TOKEN is not configured');
const headers = {Authorization: `Bearer ${token}`};
const request = async (method, path, body) =>
  await this.helpers.httpRequest({method, url: `http://127.0.0.1:8488${path}`, headers, body, json: true});

const iso = (date) => date.toISOString().slice(0, 10);
const start = new Date();
start.setHours(12, 0, 0, 0);
const daysSinceMonday = (start.getDay() + 6) % 7;
// Sunday prepares the coming week. On every other day, reconcile the current
// week's managed list so late meal-plan changes are still included.
start.setDate(start.getDate() + (start.getDay() === 0 ? 1 : -daysSinceMonday));
const end = new Date(start);
end.setDate(end.getDate() + 6);
const startDate = iso(start);
const endDate = iso(end);

const plan = await request('GET', `/api/households/mealplans?start_date=${startDate}&end_date=${endDate}&perPage=100`);
const recipeIds = [...new Set((plan.items ?? []).map((entry) => entry.recipeId).filter(Boolean))];
if (!recipeIds.length) return [{json: {created: false, reason: 'No planned recipes', startDate, endDate}}];

const listName = `Groceries ${startDate} - ${endDate}`;
const lists = await request('GET', '/api/households/shopping/lists?page=1&perPage=100');
// A user may happen to create a list with the same date-based title. Only
// reconcile lists carrying our marker; personal lists remain untouched.
let list = (lists.items ?? []).find(
  (candidate) => candidate.name === listName && candidate.extras?.yomiManaged === true,
);
if (!list) {
  list = await request('POST', '/api/households/shopping/lists', {
    name: listName,
    extras: {yomiManaged: true, startDate, endDate},
  });
}

const existing = new Set((list.recipeReferences ?? []).map((reference) => reference.recipeId));
let added = 0;
for (const recipeId of recipeIds) {
  if (existing.has(recipeId)) continue;
  await request('POST', `/api/households/shopping/lists/${list.id}/recipe/${recipeId}`, {recipeIncrementQuantity: 1});
  added += 1;
}

return [{json: {listId: list.id, listName, recipes: recipeIds.length, added}}];
